// Temporary measurement script - measures crop boundaries by pixel brightness
import sharp from 'sharp';

async function measureRows(imgPath, label) {
  const { data, info } = await sharp(imgPath)
    .raw()
    .toBuffer({ resolveWithObject: true });

  const { width, height, channels } = info;
  console.log(`\n=== ${label} ===`);
  console.log(`Size: ${width}x${height}`);

  const rowBrightness = [];
  for (let y = 0; y < height; y++) {
    let sum = 0;
    for (let x = 0; x < width; x++) {
      const offset = (y * width + x) * channels;
      sum += (data[offset] + data[offset + 1] + data[offset + 2]) / 3;
    }
    rowBrightness.push(sum / width);
  }

  return { width, height, rowBrightness };
}

async function printRows(rowBrightness, from, to, label) {
  console.log(`  ${label} (rows ${from}-${to}):`);
  for (let i = from; i <= to; i++) {
    console.log(`    row ${i}: ${rowBrightness[i].toFixed(1)}`);
  }
}

async function findTransition(rowBrightness, startRow, darkThreshold, lightThreshold) {
  // Find last dark row in a sequence starting at startRow
  let inDark = true;
  for (let y = startRow; y < rowBrightness.length; y++) {
    const b = rowBrightness[y];
    if (inDark && b > lightThreshold) {
      return y; // first non-dark row
    }
  }
  return -1;
}

// ---- dashboard.png ----
{
  const r = await measureRows('references/product-screenshots/dashboard.png', 'dashboard.png');
  // Status bar is dark, app content is light
  const statusEnd = await findTransition(r.rowBrightness, 0, 20, 30);
  console.log(`  Status bar ends at row ${statusEnd} -> crop-top = ${statusEnd}`);
  await printRows(r.rowBrightness, 0, 5, 'top rows');
  await printRows(r.rowBrightness, statusEnd - 3, statusEnd + 3, `around transition at ${statusEnd}`);
}

// ---- caution-explanation.png ----
{
  const r = await measureRows('references/product-screenshots/caution-explanation.png', 'caution-explanation.png');
  // Has status bar (dark) + browser bar (medium-dark) + app header
  // Find where brightness rises significantly (into app's "New Session" header area)
  // Print first 200 rows to inspect transition zones
  console.log('  Row brightnesses 0-200 (every 5th row):');
  for (let i = 0; i <= 200; i += 5) {
    console.log(`    row ${i}: ${r.rowBrightness[i].toFixed(1)}`);
  }
}

// ---- exercise-card-progress-message.png ----
{
  const r = await measureRows('references/product-screenshots/exercise-card-progress-message.png', 'exercise-card-progress-message.png');
  console.log('  Row brightnesses 0-200 (every 5th row):');
  for (let i = 0; i <= 200; i += 5) {
    console.log(`    row ${i}: ${r.rowBrightness[i].toFixed(1)}`);
  }
}

// ---- session-end-card.png ----
{
  const r = await measureRows('references/product-screenshots/session-end-card.png', 'session-end-card.png');
  // Need top crop (status bar + name/photo + summary card) and bottom crop (emoji row + nav bar)
  // Print row brightnesses at key regions
  console.log('  Row brightnesses 0-600 (every 10th row, looking for exercise list start):');
  for (let i = 0; i <= 600; i += 10) {
    console.log(`    row ${i}: ${r.rowBrightness[i].toFixed(1)}`);
  }
  console.log('  Row brightnesses 1600-1920 (every 10th row, looking for bottom boundary):');
  for (let i = 1600; i <= 1920; i += 10) {
    console.log(`    row ${i}: ${r.rowBrightness[i].toFixed(1)}`);
  }
}

