1	/**
2	 * Image optimisation + verification engine behind the `optimize-web-images`
3	 * skill (.claude/skills/optimize-web-images/SKILL.md).
4	 *
5	 * Safety properties enforced here, not merely documented:
6	 *   - sources are only ever READ; a SHA-256 of each is recorded so `verify`
7	 *     can prove the originals are byte-identical afterwards
8	 *   - output goes only under <root>/public/images/
9	 *   - files already under public/ are never used as sources (no recompressing
10	 *     a previous output, which would compound quality loss)
11	 *   - an existing file we did not generate is never overwritten without --force
12	 *   - no upscaling: variants wider than the source are skipped
13	 *   - EXIF/GPS metadata is stripped from every output
14	 *   - cropping only ever REMOVES edge rows (browser chrome, a status bar, a
15	 *     personal profile header). It cannot scale, stretch or re-frame, so it
16	 *     cannot misrepresent what a product screenshot shows. The amounts are
17	 *     recorded in the manifest so any crop is auditable.
18	 *
19	 * The manifest holds only measurements taken from real files, never estimates.
20	 */
21	
22	import { createHash } from 'node:crypto';
23	import { existsSync } from 'node:fs';
24	import { mkdir, readFile, stat, writeFile } from 'node:fs/promises';
25	import path from 'node:path';
26	import sharp from 'sharp';
27	import type { Metadata } from 'sharp';
28	
29	// Each file is processed once, so libvips caching gains nothing, and on Windows it
30	// keeps file handles open, which blocks deleting or regenerating those files.
31	sharp.cache(false);
32	
33	export type OutputFormat = 'webp' | 'avif' | 'jpeg';
34	
35	/** Rows removed from the top and/or bottom of the source, in source pixels. */
36	export interface Crop {
37	  top: number;
38	  bottom: number;
39	}
40	
41	export const NO_CROP: Crop = { top: 0, bottom: 0 };
42	
43	export function isCropped(crop: Crop): boolean {
44	  return crop.top > 0 || crop.bottom > 0;
45	}
46	
47	/**
48	 * The region kept after cropping. Throws rather than silently clamping: a crop
49	 * that does not fit the image is an author mistake, not something to guess at.
50	 */
51	export function cropRegion(crop: Crop, source: { width: number; height: number }) {
52	  for (const [edge, value] of Object.entries(crop)) {
53	    if (!Number.isInteger(value) || value < 0) {
54	      throw new Error(`--crop-${edge} must be a whole number of pixels >= 0, got ${value}`);
55	    }
56	  }
57	  const height = source.height - crop.top - crop.bottom;
58	  if (height <= 0) {
59	    throw new Error(
60	      `crop removes the whole image: top ${crop.top} + bottom ${crop.bottom} >= height ${source.height}`,
61	    );
62	  }
63	  return { left: 0, top: crop.top, width: source.width, height };
64	}
65	
66	export interface OptimizeOptions {
67	  /** Project root. Everything is resolved and confined relative to this. */
68	  root: string;
69	  /** Source image paths, relative to root. */
70	  sources: string[];
71	  /** Output directory, relative to root. Must be inside public/images. */
72	  outDir: string;
73	  widths: number[];
74	  format: OutputFormat;
75	  quality: number;
76	  lossless: boolean;
77	  /** Output base name; only valid with exactly one source. */
78	  name?: string;
79	  /** Rows to remove from the top/bottom of every source before resizing. */
80	  crop: Crop;
81	  dryRun: boolean;
82	  force: boolean;
83	  manifestPath: string;
84	}
85	
86	export interface SourceInfo {
87	  path: string;
88	  bytes: number;
89	  width: number;
90	  height: number;
91	  format: string;
92	  sha256: string;
93	}
94	
95	export interface OutputInfo {
96	  path: string;
97	  /** URL the app should reference, e.g. /images/product/x-800.webp */
98	  publicPath: string;
99	  width: number;
100	  height: number;
101	  format: OutputFormat;
102	  bytes: number;
103	  quality: number;
104	  lossless: boolean;
105	  /** Byte reduction versus the source file. Positive means smaller. */
106	  bytesSavedPercent: number;
107	}
108	
109	export interface ManifestEntry {
110	  source: SourceInfo;
111	  outputs: OutputInfo[];
112	  skippedWidths: number[];
113	  /** Present only when rows were removed, so an untouched entry stays unchanged. */
114	  crop?: Crop;
115	}
116	
117	export interface Manifest {
118	  schemaVersion: 1;
119	  generator: string;
120	  sharpVersion: string;
121	  entries: Record<string, ManifestEntry>;
122	}
123	
124	const SOURCE_EXTENSIONS = new Set(['.png', '.jpg', '.jpeg', '.webp', '.tif', '.tiff']);
125	const KEBAB = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;
126	
127	export function toPosix(p: string): string {
128	  return p.split(path.sep).join('/');
129	}
130	
131	/** `workout_01 Final.PNG` -> `workout-01-final` */
132	export function slugify(fileName: string): string {
133	  return path
134	    .basename(fileName, path.extname(fileName))
135	    .toLowerCase()
136	    .replace(/[^a-z0-9]+/g, '-')
137	    .replace(/^-+|-+$/g, '');
138	}
139	
140	export function parseWidths(input: string): number[] {
141	  const widths = input.split(',').map((part) => Number(part.trim()));
142	  if (widths.some((w) => !Number.isInteger(w) || w <= 0)) {
143	    throw new Error(`--widths must be positive whole numbers, got "${input}"`);
144	  }
145	  return [...new Set(widths)].sort((a, b) => a - b);
146	}
147	
148	/** Variants at or below the source width. Never upscales. */
149	export function chooseWidths(requested: readonly number[], sourceWidth: number) {
150	  const usable = requested.filter((w) => w <= sourceWidth);
151	  const skipped = requested.filter((w) => w > sourceWidth);
152	  // Everything was wider than the source: keep a single native-size variant.
153	  return { usable: usable.length > 0 ? usable : [sourceWidth], skipped };
154	}
155	
156	export function outputName(base: string, width: number, format: OutputFormat): string {
157	  const ext = format === 'jpeg' ? 'jpg' : format;
158	  return `${base}-${width}.${ext}`;
159	}
160	
